with candidate (n, title, artist, image_url, content, image_license, image_credit, image_page) as (
    values
    (1, 'バベルの塔', 'ピーテル・ブリューゲル（父）', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4f/Pieter_Bruegel_d._%C3%84.%2C_Kunsthistorisches_Museum_Wien%2C_Gem%C3%A4ldegalerie_-_Turmbau_zu_Babel_-_GG_1026_-_Kunsthistorisches_Museum.jpg/960px-Pieter_Bruegel_d._%C3%84.%2C_Kunsthistorisches_Museum_Wien%2C_Gem%C3%A4ldegalerie_-_Turmbau_zu_Babel_-_GG_1026_-_Kunsthistorisches_Museum.jpg', '旧約聖書の「創世記」で、ひとつの言葉を話す人々が天に届く塔を建てようとした物語を描いた板絵です。ウィーン美術史美術館にある作品には1563年の年記があり、アーチが幾重にも重なる巨大な塔が町を見下ろしてそびえます。足場や起重機、石を運ぶ人々など、工事の様子が驚くほど細かく描き込まれ、近づくほど発見があります。ブリューゲルはこの主題を繰り返し描き、ロッテルダムのボイマンス・ファン・ベーニンゲン美術館にも小さな1点が残っています。', 'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Pieter_Bruegel_d._Ä.,_Kunsthistorisches_Museum_Wien,_Gemäldegalerie_-_Turmbau_zu_Babel_-_GG_1026_-_Kunsthistorisches_Museum.jpg'),
    (2, '谿山行旅図', '范寛', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b1/%E8%B0%BF%E5%B1%B1%E8%A1%8C%E6%97%85%E5%9B%BE%E8%BD%B4.%E6%BA%AA%E5%B1%B1%E8%A1%8C%E6%97%85%E5%9B%BE.%E5%AE%8B.%E8%8C%83%E5%AE%BD.%E7%BB%A2%E6%9C%AC%E6%B5%85%E8%AE%BE%E8%89%B2.%E5%8F%B0%E5%8C%97%E6%95%85%E5%AE%AB%E5%8D%9A%E7%89%A9%E9%99%A2%E8%97%8F.jpg/960px-%E8%B0%BF%E5%B1%B1%E8%A1%8C%E6%97%85%E5%9B%BE%E8%BD%B4.%E6%BA%AA%E5%B1%B1%E8%A1%8C%E6%97%85%E5%9B%BE.%E5%AE%8B.%E8%8C%83%E5%AE%BD.%E7%BB%A2%E6%9C%AC%E6%B5%85%E8%AE%BE%E8%89%B2.%E5%8F%B0%E5%8C%97%E6%95%85%E5%AE%AB%E5%8D%9A%E7%89%A9%E9%99%A2%E8%97%8F.jpg', '北宋初期の山水画家・范寛の代表作で、現存するほぼ唯一の作品ともいわれる大きな掛軸です。画面の上半分を巨大な岩山が占め、その足もとの林から、荷を積んだ馬の列が小さく姿を現します。手前、水と霧の中景、奥の山という三つの層で奥行きをつくり、自然の雄大さそのものを主題にしました。後の山水画家たちが繰り返し手本とした記念碑的な作品で、台北の国立故宮博物院が所蔵しています。', 'Public domain', null, 'https://commons.wikimedia.org/wiki/File:谿山行旅图轴.溪山行旅图.宋.范宽.绢本浅设色.台北故宫博物院藏.jpg')
), fresh as (
    select c.*, row_number() over (order by c.n) as k
    from candidate c
    where not exists (select 1 from public.daily_columns d where d.title = c.title)
), free_day as (
    select day::date as display_date, row_number() over (order by day) as k
    from generate_series(
        (now() at time zone 'Asia/Tokyo')::date,
        (now() at time zone 'Asia/Tokyo')::date + 2
            + (select count(*)::int from public.daily_columns
               where display_date >= (now() at time zone 'Asia/Tokyo')::date),
        interval '1 day') as day
    where not exists (select 1 from public.daily_columns d where d.display_date = day::date)
)
insert into public.daily_columns (title, artist, image_url, content, image_license, image_credit, image_page, display_date)
select f.title, f.artist, f.image_url, f.content, f.image_license, f.image_credit, f.image_page, d.display_date
from fresh f join free_day d using (k)
on conflict (display_date) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('東京国立近代美術館、初の速水御舟展を2027年に', '東京国立近代美術館が2027年の展覧会予定を発表。同館初の速水御舟展や、山口晃展、ミルトン・エイヴリー展が並ぶ。', '東京国立近代美術館が2027年の展覧会スケジュールを発表した。開催中の「竹久夢二 時代を創る表現者」に続き、「斬新！ 速水御舟」（2027年3月19日～5月9日）、「山口晃 見／世／物」（6月18日～8月29日）、「ミルトン・エイヴリー展」（仮称、10月9日～2028年1月30日予定）を開く。御舟展は同館の70年を超える歴史で初めてで、国立美術館としては1980年の京都国立近代美術館以来47年ぶり。同館が約5年前から調査してきた日記や書簡などの資料とあわせ、約100点の作品を紹介する。エイヴリー展は、日本で初めて本格的にこの画家を取り上げる展覧会となる。', '', '展覧会', 'https://artexhibition.jp/topics/news/20261029-AEJ3031010/',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('箱根美術館、改修を終えプレオープン', '箱根で最も歴史のある箱根美術館が、約半年の改修工事を経て10月30日にプレオープンした。', '神奈川県箱根町強羅の箱根美術館が、令和8年（2026年）5月7日から続いた改修工事に伴う全面休館を終え、10月30日にプレオープンした。工事は約半年にわたった。同館は昭和27年に開館した箱根で最も歴史のある美術館で、縄文時代の土器から鎌倉・室町時代の六古窯の壺や甕、江戸時代に至る日本のやきものを中心に展示している。館が建つ庭園「神仙郷」は、創立者の岡田茂吉が昭和19年から28年にかけて造営したもので、令和3年に国の名勝に指定された。新たに設けられたカフェ「THE CAFÉ & BAKERY」は、人間国宝の技が彩る空間として紹介されている。', '', '美術館', 'https://moaart.or.jp/hakone/',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('坂本龍一の演奏データで新作、MoN Takanawaで', '坂本龍一が遺した演奏データを使うプロジェクト「Ryuichi Sakamoto | Dialogue」が12月24日から東京・高輪で開かれる。', '2023年に亡くなった音楽家・坂本龍一が遺したMIDIなどの演奏データを活用し、アーティストとの協働で新たな音楽体験を生み出すプロジェクト「Ryuichi Sakamoto | Dialogue」が、東京・高輪の文化施設「MoN Takanawa: The Museum of Narratives」で開かれる。ピアニストの角野隼斗とアーティストの真鍋大度による『D』（12月24日～26日）では、角野が坂本の作品を演奏し、遺された演奏データによる自動演奏ピアノと共演する。真鍋は立体音響と映像で、二人の演奏が交差する空間をつくる。2027年1月8日～17日には、古舘健と濵哲史による『Opus — dialogue』を上演する。', '', '作品・作家', 'https://bijutsutecho.com/magazine/news/exhibition/33268',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('盲目の少女', 'The Blind Girl', 'ジョン・エヴァレット・ミレー', 'John Everett Millais',
        1856,
        (select slug from public.art_movements where slug = 'pre-raphaelite'),
        'バーミンガム美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7a/John_Everett_Millais_-_The_Blind_Girl%2C_1854-56.jpg/960px-John_Everett_Millais_-_The_Blind_Girl%2C_1854-56.jpg', '雨上がりの道ばたで休む、旅の物乞いの姉妹を描いた作品です。盲目の姉はひざにコンサーティーナを置き、顔に当たる日のぬくもりを感じながら草の葉に触れています。妹は振り返り、空にかかった二重の虹を見上げています。見える者と見えない者の感覚を対比した寓意とも読まれます。発表後、二重の虹では外側の虹の色の順が逆になると指摘され、ミレーは科学的な正しさのために描き直しました。自然を細部まで忠実に描くというラファエル前派の理念を、同時代の名もない人々の姿に向けた一枚です。',
        'Public domain', null, 'https://commons.wikimedia.org/wiki/File:John_Everett_Millais_-_The_Blind_Girl,_1854-56.jpg')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

