    image_license, image_credit, image_page)
values ('ヒュラスとニンフたち', 'Hylas and the Nymphs', 'ジョン・ウィリアム・ウォーターハウス', 'John William Waterhouse',
        1896,
        (select slug from public.art_movements where slug = 'pre-raphaelite'),
        'マンチェスター美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bd/Waterhouse_Hylas_and_the_Nymphs_Manchester_Art_Gallery_1896.15.jpg/960px-Waterhouse_Hylas_and_the_Nymphs_Manchester_Art_Gallery_1896.15.jpg', 'ギリシア・ローマ神話の若者ヒュラスが、水を汲みに来た池で水の精ナーイアスたちに引き込まれる場面を描いた作品です。ヒュラスは英雄ヘラクレスの従者としてアルゴー船の旅に加わり、水を探しに出たまま姿を消したと伝えられます。暗い水面から、よく似た顔の少女たちが手を伸ばし、青い衣に赤い帯を締めたヒュラスを誘います。ウォーターハウスはラファエル前派が好んだ文学や神話の主題を受け継ぎながら、より柔らかな筆づかいで、19世紀末らしい夢のような雰囲気を描きました。',
        'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Waterhouse_Hylas_and_the_Nymphs_Manchester_Art_Gallery_1896.15.jpg')
