insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('范寛', 'Fan Kuan', '范寛',
        null, null, 'east_asia', array['song-yuan']::text[],
        '雄大な自然そのものを主題にした、北宋初期を代表する山水画家。', '中国・北宋初期の山水画家で、もとの名は中正、字は中立といいます。耀州華原県（現在の陝西省）の出身で、10世紀後半から11世紀前半に活躍しました。道家と儒家の両方の思想を持った人物と伝えられ、先輩の山水画家・李成から影響を受けました。

代表作「谿山行旅図」は、画面の上半分を占める巨大な岩山の足もとに、荷を運ぶ小さな馬の列を描いた大きな掛軸です。手前・中景・遠景の三つの層で奥行きをつくり、それまで背景にとどまりがちだった自然の雄大さを主題に据えました。

この作品は北宋の山水画の礎とされ、後の画家たちが繰り返し手本としました。「雪山楼閣図」「雪景山水図」なども范寛の作と伝わります。1999年には雑誌『ライフ』の「この1000年で最も重要な功績を残した世界の人物100人」で、東洋の画家として最高の59位に選ばれています。', 'https://ja.wikipedia.org/wiki/%E8%8C%83%E5%AF%9B')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('狩野芳崖', 'Kanō Hōgai', '芳崖',
        1828, 1888, 'japan', array['kano', 'nihonga']::text[],
        '狩野派の伝統に西洋の写実と色彩を取り入れた、「近代日本画の父」と呼ばれる画家。', '長府藩の狩野派御用絵師の家に生まれ、19歳で江戸の木挽町狩野家に入門しました。同日に入門した橋本雅邦とは生涯の友となり、二人は「竜虎」と並び称されました。明治維新後は生活に苦しみ、上京後も陶磁器の下絵を描いて暮らしをしのぎました。

転機は、日本美術を高く評価したアメリカ人の美術史家フェノロサとの出会いです。フェノロサは、日本画の伝統に西洋絵画の写実や空間表現を取り入れた新しい日本画を芳崖に託しました。鮮やかな西洋顔料を使った「仁王捉鬼図」は鑑画会で一等となり、東京美術学校設立のきっかけにもなりました。

最晩年の「悲母観音」は、仏画や水墨画の描法と西洋画の色彩感覚・空間把握を融合させた名作です。芳崖はこの絵を描き上げた4日後、東京美術学校の開校を待たずに亡くなりましたが、雅邦とともに江戸時代と明治時代の日本画を橋渡しする役割を果たしました。', 'https://ja.wikipedia.org/wiki/%E7%8B%A9%E9%87%8E%E8%8A%B3%E5%B4%96')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('浅井忠', 'Asai Chū', '浅井忠',
        1856, 1907, 'japan', array['yoga-meiji']::text[],
        '工部美術学校でフォンタネージに学び、明治の洋画を育てた画家・教育者。', '江戸の佐倉藩中屋敷に藩士の子として生まれ、少年時代を佐倉で過ごしました。13歳ごろから藩の南画家に花鳥画を学び、上京後は国沢新九郎の彰技堂で油絵を学んだのち、工部美術学校でイタリア人画家フォンタネージの薫陶を受けました。

1889年には中心となって明治美術会を設立し、1898年に東京美術学校の教授となりました。1900年からフランスに留学し、帰国後は関西に移って京都高等工芸学校の教授となります。当時の洋画界では、明るい外光派の黒田清輝と、暗い色調の浅井の作風の違いが取り沙汰されました。

京都では聖護院洋画研究所（のちの関西美術院）を開き、安井曽太郎や梅原龍三郎らを育てました。正岡子規にも西洋画を教え、夏目漱石『吾輩ハ猫デアル』の挿画も手がけています。代表作に重要文化財の「春畝」「収穫」があります。', 'https://ja.wikipedia.org/wiki/%E6%B5%85%E4%BA%95%E5%BF%A0')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();
